(()=>{const e=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const A=[{d:'2026.09.22',t:'欧洲九大药企公开警告“正在输给美国和中国”：中国药研实力已成为全球资源配置变量',s:'AstraZeneca、GSK、Novo Nordisk、Roche、Novartis、Sanofi等九家欧洲药企董事长联名公开信，称欧洲研发、临床试验和投资吸引力落后于美国和中国。',c:'组织/公司',w:'这不是普通行业倡议，而是跨国药企董事长把中国公开描述为创新与投资竞争者。',h:'<div class="reader-detail research-detail"><section class="reader-section reader-news"><h4>事实与背景</h4><p>9月22日，九家欧洲药企董事长发布公开信，称欧洲全球医药研发份额从1990年的43%降到31%，商业临床试验份额降到9%，过去两年美国和中国已宣布的医药投资超过6000亿美元；信中称中国全球临床试验份额已接近30%。Reuters、Guardian和BioPharma Dive指出，药企担心的不只是研发投入，而是审批慢、支付预算约束和上市后可及性差。</p></section><section class="reader-section"><h4>为什么对中国市场重要</h4><p>中国不再只是销售市场，而是临床执行、创新资产、生产能力和资本投入的竞争变量。对中国药企，价值评价会从国内获批前移到国际多中心证据、海外注册和全球商业化；对MNC，中国团队职责会从市场执行扩展到全球临床、BD和产品策略。</p><div class="research-chain"><span>中国临床资源</span><i>→</i><span>研发速度/成本</span><i>→</i><span>资产质量</span><i>→</i><span>总部资源倾斜</span></div></section><section class="reader-section"><h4>行业怎么看/争议</h4><div class="reader-pair"><div class="reader-piece"><h5>支持中国上升</h5><p>临床试验份额和持续license-out与行业报道方向一致。</p></div><div class="reader-piece"><h5>边界</h5><p>公开信本质上仍是欧洲药企向政策制定者施压，临床数量不等于全球商业成功，数据质量、IP、供应和可及性仍是硬约束。</p></div></div></section><section class="reader-section"><h4>对Viatris意味着什么</h4><p>对立普妥、络活喜等成熟品牌，不能直接推导销量上升，但应继续验证中国的基层、零售/DTP、患者管理和供应能力能否形成可复制的全球成熟品牌运营能力。</p></section><div class="detail-meta"><details class="meta-details"><summary>来源与延伸阅读 <span>5</span></summary><div class="meta-body"><a class="source-link" href="https://www.astrazeneca.com/media-centre/articles/2026/europe-is-losing-the-pharma-investment-race-but-the-comeback-is-within-reach.html" target="_blank">一手公开信 ↗</a><a class="source-link" href="https://www.reuters.com/legal/litigation/european-drugmakers-call-faster-trials-more-spending-compete-with-us-china-2026-09-22/" target="_blank">Reuters ↗</a><a class="source-link" href="https://www.theguardian.com/business/2026/sep/22/european-drugmakers-losing-ground-us-chinese-rivals" target="_blank">Guardian ↗</a><a class="source-link" href="https://www.biopharmadive.com/news/europe-biotech-investment-decline-letter-pharma-chairs/831112/" target="_blank">BioPharma Dive ↗</a><a class="source-link" href="https://www.reuters.com/legal/litigation/china-outpacing-europe-drug-innovation-development-pfizer-executive-says-2026-06-23/" target="_blank">Reuters/Pfizer观点 ↗</a></div></details></div></div>'},{d:'2026.09.22',t:'中国扩大对美、墨、加药物前体出口管制：供应链合规进一步前移',s:'五部门新增2种物质，向美国、墨西哥、加拿大出口目录内18种前体化学品需许可证，措施自9月22日生效。',c:'全球供应链与制造',w:'这不是普通原料药新闻，而是出口许可、最终用途核查和地缘政治风险进入跨国药企供应决策。',h:'<div class="reader-detail research-detail"><section class="reader-section reader-news"><h4>事实层</h4><p>中国商务部、公安部、应急管理部、海关总署和国家药监局联合调整目录，新增2种物质，针对美国、墨西哥和加拿大的受控化学品增至18种，出口需申请许可证。Reuters、AP和MLex确认这是2025年11月、2026年5月之后的第三轮扩围，规则立即生效。</p></section><section class="reader-section"><h4>机制：从采购问题变成许可问题</h4><p>影响不一定先表现为成品药断供，更可能表现为最终用户核查、许可证审批、交付周期、供应商分散化和安全库存增加。跨境生产链如果经过中国原料、中间体、海外API和北美制剂，任何许可证延迟都可能传导到交付。</p><div class="research-chain"><span>订单</span><i>→</i><span>用途/最终用户</span><i>→</i><span>许可证</span><i>→</i><span>海关审查</span><i>→</i><span>交付</span></div></section><section class="reader-section"><h4>行业怎么看/边界</h4><div class="reader-pair"><div class="reader-piece"><h5>强硬解读</h5><p>谈判节点前扩围，可能被视为把供应链当作政策工具。</p></div><div class="reader-piece"><h5>更准确解读</h5><p>这不是对所有国家全面禁运，而是对三个国家实施许可管理；短期风险取决于审批效率和企业合规质量。</p></div></div></section><section class="reader-section"><h4>对Viatris意味着什么</h4><p>应沿核心SKU做mapping：API/中间体是否依赖中国供应商，是否涉及三国出口，安全库存能否覆盖许可波动，替代供应商和生产地是否完成质量与注册评估。</p></section><div class="detail-meta"><details class="meta-details"><summary>来源与延伸阅读 <span>5</span></summary><div class="meta-body"><a class="source-link" href="https://la.china-embassy.gov.cn/eng/news/202609/t20260923_12029503.htm" target="_blank">一手/新华社转发 ↗</a><a class="source-link" href="https://www.reuters.com/business/healthcare-pharmaceuticals/china-expands-export-control-list-drug-precursor-chemicals-ahead-trump-xi-summit-2026-09-22/" target="_blank">Reuters ↗</a><a class="source-link" href="https://apnews.com/article/6e3012905f3263b796325c03e94d1e40" target="_blank">AP ↗</a><a class="source-link" href="https://www.mlex.com/mlex/articles/2528225" target="_blank">MLex ↗</a><a class="source-link" href="https://www.geopolitechs.org/p/china-expands-controls-on-fentanyl" target="_blank">行业观察 ↗</a></div></details></div></div>'}];function r(){const b=document.querySelector('#weeklyFocus');if(!b)return;b.innerHTML=A.map(x=>'<article class="focus-card"><div class="focus-top"><h3>'+e(x.t)+'</h3><span class="date">'+x.d+'</span></div><p class="focus-summary">'+e(x.s)+'</p><div class="chips"><span class="chip">'+e(x.c)+'</span><span class="chip v">Viatris高相关</span></div><div class="why-now"><b>为什么值得看：</b>'+e(x.w)+'</div><button class="open-link" data-v32>展开深度解读 ↓</button><div class="weekly-detail" hidden>'+x.h+'</div></article>').join('');document.querySelectorAll('[data-v32]').forEach(q=>q.onclick=()=>{const d=q.nextElementSibling;d.hidden=!d.hidden;q.textContent=d.hidden?'展开深度解读 ↓':'收起深度解读 ↑'});document.querySelector('#weeklyMetrics').innerHTML='<div class="metric"><b>2</b><span>本期重点</span></div><div class="metric"><b>2</b><span>深度研究卡</span></div><div class="metric"><b>2</b><span>Viatris高相关</span></div>';document.querySelector('#weeklyJudgements').innerHTML=['中国已成为全球药企研发、临床和BD资源配置中的独立变量。','供应链管制进入合规与库存决策，但不能直接等同于断供。','成熟品牌竞争力越来越取决于渠道、供应和患者管理能力。'].map(x=>'<div class="insight-item">'+e(x)+'</div>').join('');document.querySelector('#weeklyValidation').innerHTML=['欧洲药企倡议能否转化为具体改革。','许可审批是否出现延迟或企业库存上调。','Viatris核心SKU是否存在中国供应链单点风险。'].map(x=>'<div class="insight-item">'+e(x)+'</div>').join('')}document.addEventListener('radar:ready',r,{once:true})})()